  const invoices = [
    {
      number: '001',
      customerName: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 100, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);

  assert(csv.endsWith('\n'));
});

